-- Stores or replaces the certificate of a device; a suspension is kept (ADR 0012 §6), and stored_at_ms moves only when the certificate bytes change, so it still tells whether a device was in the restored set (INV-59). Shared by both engines; every value is a bound parameter (INV-53).
INSERT INTO auth_device_certificates (account_id, device_id, identity_epoch, device_kind, expires_at_ms, certificate, suspended_at_ms, stored_at_ms) VALUES ($1, $2, $3, $4, $5, $6, NULL, $7) ON CONFLICT (account_id, device_id) DO UPDATE SET identity_epoch = excluded.identity_epoch, device_kind = excluded.device_kind, expires_at_ms = excluded.expires_at_ms, stored_at_ms = CASE WHEN auth_device_certificates.certificate = excluded.certificate THEN auth_device_certificates.stored_at_ms ELSE excluded.stored_at_ms END, certificate = excluded.certificate
